<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/app/bootstrap.php';
use VideoLibrary\{Auth, Input, LibraryService, LibraryStore, Web};
try {
    $config = Web::config(); Web::get(); Input::fields($_GET, ['id']); $operator = Auth::requireOperator($config);
    $video = (new LibraryService(new LibraryStore($config, $operator['id'])))->video(Input::id($_GET['id']));
    $token = Auth::token($video['id']); $csrf = Auth::csrf(); Web::head('Player', $csrf);
    echo '<link rel="stylesheet" href="/watermark.php?id=' . $video['id'] . '"><div class="page-heading"><div><p class="eyebrow">PLAYER DENGAN OVERLAY</p><h1>' . Web::escape($video['originalName']) . '</h1><p>Penanda terlihat di halaman ini. File video tidak ditranscode atau diberi watermark permanen.</p></div><a class="button secondary" href="/list.php">Kembali ke library</a></div><section class="panel player-panel"><div class="video-frame" id="video-frame" data-position="' . $video['watermark']['position'] . '"><video id="player" controls preload="metadata" playsinline><source src="/stream.php?id=' . $video['id'] . '&amp;token=' . $token . '" type="' . Web::escape($video['mime']) . '">Browser ini belum mendukung format video ini.</video><span class="watermark player-watermark" aria-hidden="true">' . Web::escape($video['watermark']['text']) . '</span></div><p class="hint">Overlay dibatasi area video; teks panjang atau besar dapat terpotong. Teks lengkap tetap tersedia di bawah.</p><p class="watermark-copy">Teks lengkap: ' . Web::escape($video['watermark']['text'] === '' ? '(teks kosong)' : $video['watermark']['text']) . '</p><p id="player-status" role="status">Token berlaku maksimal20 menit. Buka ulang player bila sesi atau token berakhir.</p><div class="actions"><button id="fullscreen" type="button" hidden>Fullscreen dengan overlay</button><a class="button secondary" href="/player.php?id=' . $video['id'] . '">Buka ulang player</a></div></section><section class="panel"><h2>Yang ditampilkan</h2><p>Ukuran ' . $video['watermark']['size'] . 'px, opacity ' . $video['watermark']['opacity'] . '%, posisi ' . Web::escape($video['watermark']['position']) . '. Dukungan codec bergantung browser. Tombol fullscreen khusus memakai wadah overlay jika tersedia; fullscreen video native bisa hanya menampilkan video.</p><p>Ini bukan DRM atau proteksi download. Pengguna yang sudah menerima byte tetap dapat menyimpannya. Penghapusan/logout menolak permintaan baru, bukan menarik byte yang sudah terkirim.</p></section>';
    Web::foot();
} catch (Throwable $error) { Web::problem($error); }
